// Player Database V2 — curated modern players (Phase A).
//
// FACTUAL fields (name, nationId, clubId, positions) reflect football reality
// at the 2026-07-07 research cutoff, with verified summer-2026 moves applied
// (see transferIntel.2026-07-07.json for the sourced deltas). GAME-DESIGN
// fields (primaryRole, tier, character, signatures, developmentProfile) are
// Final XI judgements — not researched facts, not market value.
//
// leagueId is intentionally NOT stored on the player: it is derived from the
// club and enforced by the validator, avoiding a second source of truth.
//
// M(id, name, primaryPosition, nationId, clubId, secondaryPositions,
//   primaryRole, tier, character, signatures, developmentProfile)
const M = (id, name, primaryPosition, nationId, clubId, secondaryPositions, primaryRole, tier, character, signatures, developmentProfile) => ({
  id, name, primaryPosition, secondaryPositions, nationId, clubId,
  primaryRole, tier, character, signatures, developmentProfile, era: 'modern',
})

